import { useForm } from "react-hook-form";
import {
  FormEngineRoot,
  FormEngineProgress,
  FormEngineStepMeta,
  FormEngineStep,
  FormEngineNavigation,
  type FormEngineStepDef,
} from "@/components/bevelui/form-engine";
import { Input } from "@/components/ui/input";
import { CardSelect } from "@/components/bevelui/controls/card-select";

export function OnboardingForm() {
  const form = useForm();

  // Step validate functions gate navigation without the engine knowing
  // which library is handling state. Return a boolean or Promise<boolean>.
  const steps: FormEngineStepDef[] = [
    {
      id: "account",
      title: "Create your account",
      description: "Your login details.",
      validate: () => form.trigger(["name", "email", "password"]),
    },
    {
      id: "plan",
      title: "Choose a plan",
      validate: () => form.trigger(["plan"]),
    },
  ];

  return (
    <FormEngineRoot
      config={{ steps }}
      onSubmit={form.handleSubmit(async (values) => createAccount(values))}
    >
      <FormEngineProgress />
      <FormEngineStepMeta />

      <FormEngineStep id="account" className="flex flex-col gap-4">
        <Input {...form.register("name", { required: true })} placeholder="Full name" />
        <Input {...form.register("email", { required: true })} type="email" placeholder="Email" />
        <Input {...form.register("password", { required: true })} type="password" placeholder="Password" />
      </FormEngineStep>

      <FormEngineStep id="plan">
        <CardSelect
          options={planOptions}
          value={form.watch("plan")}
          onChange={(v) => form.setValue("plan", v)}
        />
      </FormEngineStep>

      <FormEngineNavigation submitLabel="Create account" />
    </FormEngineRoot>
  );
}

